const webhookBody =
  $("Webhook - Sprint Report").first().json.body || {};

const requestedSprint = webhookBody.sprint || "Sprint 1";
const question = webhookBody.question || "";

const tasks = $input.all()
  .map(item => {
    const row = item.json;

    return {
      task_id: String(row.task_id || "").trim(),
      task_name: String(row.task_name || "").trim(),
      description: String(row.description || "").trim(),
      status: String(row.status || "Unknown").trim(),
      assignee: String(row.assignee || "").trim(),
      priority: String(row.priority || "Unknown").trim(),
      sprint: String(row.sprint || "").trim(),
      start_date: String(row.start_date || "").trim(),
      due_date: String(row.due_date || "").trim(),
      last_updated: String(row.last_updated || "").trim(),
      blocked: String(row.blocked || "No").trim(),
      blocker_reason: String(row.blocker_reason || "").trim(),
      dependencies: String(row.dependencies || "").trim(),
      tags: String(row.tags || "").trim()
    };
  })
  .filter(task => task.sprint === requestedSprint);

const latestDatasetDate =
  tasks
    .map(task => task.last_updated)
    .filter(Boolean)
    .sort()
    .pop() || new Date().toISOString().slice(0, 10);

const reportDate =
  webhookBody.report_date || latestDatasetDate;

const completedStatuses = ["done", "completed", "closed"];
const statusCounts = {};

for (const task of tasks) {
  statusCounts[task.status] =
    (statusCounts[task.status] || 0) + 1;
}

const blockedTasks = tasks.filter(task => {
  const status = task.status.toLowerCase();
  const blocked = task.blocked.toLowerCase();

  return (
    blocked === "yes" ||
    blocked === "true" ||
    status.includes("blocked") ||
    status.includes("stuck")
  );
});

const overdueTasks = tasks.filter(task => {
  const completed = completedStatuses.includes(
    task.status.toLowerCase()
  );

  return (
    task.due_date &&
    task.due_date < reportDate &&
    !completed
  );
});

const unassignedTasks =
  tasks.filter(task => !task.assignee);

const completedCount =
  tasks.filter(task =>
    completedStatuses.includes(task.status.toLowerCase())
  ).length;

const completionRate = tasks.length
  ? Math.round((completedCount / tasks.length) * 100)
  : 0;

let sprintHealth = "HEALTHY";

if (blockedTasks.length >= 2 || overdueTasks.length >= 3) {
  sprintHealth = "CRITICAL";
} else if (
  blockedTasks.length === 1 ||
  overdueTasks.length > 0 ||
  unassignedTasks.length > 0
) {
  sprintHealth = "AT RISK";
}

return [
  {
    json: {
      reportDate,
      requestedSprint,
      question,
      totalTasks: tasks.length,
      completedCount,
      completionRate,
      statusCounts,
      blockedCount: blockedTasks.length,
      overdueCount: overdueTasks.length,
      unassignedCount: unassignedTasks.length,
      sprintHealth,
      blockedTasks,
      overdueTasks,
      unassignedTasks,
      tasks
    }
  }
];

const sprint =
  $("Process Sprint Data").first().json;

const mem0Response =
  $input.first().json || {};

const memories = Array.isArray(mem0Response.results)
  ? mem0Response.results
  : [];

const memorySummaries = memories.map(memory => ({
  id: memory.id || "",
  memory: memory.memory || "",
  score: memory.score || 0,
  metadata: memory.metadata || {},
  created_at: memory.created_at || ""
}));

const historicalText = memorySummaries
  .map(memory => memory.memory)
  .join(" ")
  .toLowerCase();

const stuckTasks = sprint.blockedTasks.filter(task => {
  const taskId = task.task_id.toLowerCase();
  const taskName = task.task_name.toLowerCase();

  return (
    historicalText.includes(taskId) ||
    historicalText.includes(taskName)
  );
});

const trendText = memories.length === 0
  ? "No previous sprint snapshots are available yet. This is the baseline report."
  : `Compared the current sprint with ${memories.length} previous memory records.`;

return [
  {
    json: {
      ...sprint,
      historyCount: memories.length,
      historicalMemories: memorySummaries,
      stuckTasks,
      stuckTaskCount: stuckTasks.length,
      trendText
    }
  }
];

