const context =
  $("Prepare Agent Context").first().json;

const analysis =
  $("Nebius - Sprint Analyzer").first()
    .json.choices[0].message.content;

const report =
  $("Nebius - Report Generator").first()
    .json.choices[0].message.content;

const memoryResponse =
  $input.first().json || {};

return [
  {
    json: {
      success: true,
      reportDate: context.reportDate,
      sprint: context.requestedSprint,
      question: context.question,
      sprintHealth: context.sprintHealth,
      totalTasks: context.totalTasks,
      completedCount: context.completedCount,
      completionRate: context.completionRate,
      blockedCount: context.blockedCount,
      overdueCount: context.overdueCount,
      unassignedCount: context.unassignedCount,
      stuckTaskCount: context.stuckTaskCount,
      trend: context.trendText,
      historyDepth: context.historyCount + 1,
      memoryStatus:
        memoryResponse.status ||
        memoryResponse.message ||
        "submitted",
      analysis,
      report
    }
  }
];
